// Icon lookup for `[icon: name]`.
// - Tech logos (`postgres`, `k8s`, `redis`, ...) draw a Simple Icons logo (CC0-1.0).
// - General names (`users`, `key`, `shield`, ...) draw a Lucide icon (ISC).
// - Cloud vendor names (`aws-ec2`, `gcp-cloud-sql`, ...) map to a generic glyph by keyword, drawn
//   with Lucide. No AWS / Google Cloud / Azure artwork is bundled.
// - Anything else gets our own neutral placeholder.
// `GLYPHS` is our own small outline set (24x24, stroke only), kept as the fallback artwork.
// Icon data is generated by scripts/build-icons.mjs into icon-data.ts.

import { LUCIDE_ICONS, SIMPLE_ICONS } from './icon-data.ts';

export type Glyph =
  | 'user'
  | 'users'
  | 'server'
  | 'database'
  | 'monitor'
  | 'phone'
  | 'cloud'
  | 'queue'
  | 'balancer'
  | 'function'
  | 'bucket'
  | 'bolt'
  | 'container'
  | 'lock'
  | 'globe'
  | 'flag'
  | 'mail'
  | 'file'
  | 'gear'
  | 'chart'
  | 'code'
  | 'bell'
  | 'search'
  | 'placeholder';

